xpath.script:
document.addEventListener("DOMContentLoaded", function () {
    const customFilters = document.getElementById("xevoria_custom_filters");
    if (!customFilters) return;

    const sidebar = Array.from(document.querySelectorAll("div")).find(function (el) {
        const text = el.innerText || "";
        return text.includes("Tags") &&
               !text.includes("All products");
    });

    if (sidebar && !sidebar.contains(customFilters)) {
        customFilters.style.display = "block";
        sidebar.appendChild(customFilters);
    }

    document.querySelectorAll(".xevoria_filter_checkbox").forEach(function (checkbox) {
        const url = checkbox.getAttribute("data-url");
        if (!url) return;

        const currentPath = window.location.pathname + window.location.search;

        if (currentPath === url || window.location.href.includes(url)) {
            checkbox.checked = true;
        }

        checkbox.addEventListener("click", function (ev) {
            ev.stopPropagation();
            window.location.href = url;
        });
    });

    document.querySelectorAll(".xevoria_filter_link").forEach(function (label) {
        label.addEventListener("click", function () {
            const checkbox = label.querySelector(".xevoria_filter_checkbox");
            if (!checkbox) return;

            const url = checkbox.getAttribute("data-url");
            if (url) {
                window.location.href = url;
            }
        });
    });

    document.querySelectorAll(".xevoria_filter_title").forEach(function (title) {
        title.style.cursor = "pointer";

        title.addEventListener("click", function () {
            const section = title.closest(".xevoria_filter_section");
            if (!section) return;

            const list = section.querySelector("ul");
            const arrow = title.querySelector(".xevoria-arrow");

            if (!list) return;

            if (list.style.display === "none") {
                list.style.display = "block";
                if (arrow) {
                    arrow.classList.remove("rotate");
                }
            } else {
                list.style.display = "none";
                if (arrow) {
                    arrow.classList.add("rotate");
                }
            }
        });
    });
});
